"""The PayPal client: the ONLY module that imports the PayPal SDK or talks to PayPal's API (SPEC 9.7, 12).

* SDK (`paypal-server-sdk`, generated by APIMatic) for Orders v2, Payments v2 and Transaction Search. Every option key and
  model field used below was read from the installed package, not from memory.
* `httpx` only where the SDK has no coverage: Payouts v1, webhook signature verification and the OAuth token those need.

It implements three roles, handed out separately so least privilege is visible:
  - reader  (`PayPalReader`): Guardian lookups G-06 / G-08;
  - writer  (`PayPalWriter`): capture / void / refund / payout, called ONLY by `money_executor`;
  - orders  (`OrderGateway`): the buyer-side create-order / authorize calls behind the Pledge Gate.
Errors are translated once, here: transient (timeouts, 429, 5xx) vs rejected (4xx), reads that cannot be answered
become `PayPalUnavailable`. Sandbox only: any other environment is refused.
"""
import json
import re
import time
from decimal import Decimal

import httpx
from paypalserversdk.configuration import Environment
from paypalserversdk.exceptions.api_exception import ApiException
from paypalserversdk.http.auth.o_auth_2 import ClientCredentialsAuthCredentials
from paypalserversdk.models.capture_request import CaptureRequest
from paypalserversdk.models.checkout_payment_intent import CheckoutPaymentIntent
from paypalserversdk.models.amount_with_breakdown import AmountWithBreakdown
from paypalserversdk.models.money import Money
from paypalserversdk.models.order_request import OrderRequest
from paypalserversdk.models.purchase_unit_request import PurchaseUnitRequest
from paypalserversdk.models.refund_request import RefundRequest
from paypalserversdk.paypal_serversdk_client import PaypalServersdkClient

from app.services.guardian_rules import PayPalObject, PayPalUnavailable
from app.services.paypal_io import PayPalWriteError

SANDBOX_API = "https://api-m.sandbox.paypal.com"
CONNECTION_ERRORS = (httpx.TransportError, ConnectionError, TimeoutError, OSError)


class PayPalConfigError(Exception):
    pass


# ---------------- money <-> PayPal strings (exact, no floats) ----------------

def cents_to_value(cents: int) -> str:
    if not isinstance(cents, int) or isinstance(cents, bool) or cents < 0:
        raise ValueError(f"amount must be non-negative integer cents, got {cents!r}")
    return f"{cents // 100}.{cents % 100:02d}"


_PLAIN_AMOUNT = re.compile(r"^\d+(\.\d{1,2})?$")


def value_to_cents(value: str | None) -> int:
    """'400.00' -> 40000. Only plain decimal text with at most two decimals (no exponents, signs or spaces)."""
    text = str(value)
    if not _PLAIN_AMOUNT.fullmatch(text):  # fullmatch: `$` alone would also accept a trailing newline
        raise ValueError(f"not a USD amount: {value!r}")
    return int(Decimal(text) * 100)


def _money(cents: int, currency: str) -> Money:
    if currency != "USD":
        raise PayPalWriteError(f"only USD is supported in this build, not {currency}", transient=False)
    try:
        return Money(currency_code=currency, value=cents_to_value(cents))
    except ValueError as e:
        raise PayPalWriteError(f"refusing to send an invalid amount: {e}", transient=False) from e


def _opt(obj, name):
    """The SDK leaves an optional field UNSET (the attribute does not exist) when PayPal omits it, so never read one directly."""
    return getattr(obj, name, None) if obj is not None else None


def _status(obj) -> str:
    """The object's status text, or 'UNKNOWN' (which the Guardian treats as a mismatch) if PayPal omitted it."""
    st = _opt(obj, "status")
    return str(st) if st else "UNKNOWN"


# ---------------- error translation ----------------

def _body_info(exc: ApiException) -> tuple[str, str | None]:
    """(message, debug_id) from the response body when it is JSON; PayPal always includes debug_id on errors."""
    try:
        data = json.loads(getattr(exc.response, "text", "") or "{}")
    except (ValueError, TypeError):
        return str(exc.reason), None
    msg = data.get("message") or data.get("name") or str(exc.reason)
    details = data.get("details") or []
    if details and isinstance(details[0], dict) and details[0].get("issue"):
        msg = f"{msg} ({details[0]['issue']})"
    return msg, data.get("debug_id")


def _is_transient(status: int) -> bool:
    return status == 429 or status >= 500


def _write_error(exc: Exception) -> PayPalWriteError:
    if isinstance(exc, ApiException):
        msg, debug = _body_info(exc)
        return PayPalWriteError(f"PayPal {exc.response_code}: {msg}", transient=_is_transient(exc.response_code), debug_id=debug)
    return PayPalWriteError(f"could not reach PayPal: {type(exc).__name__}: {exc}", transient=True)


# ---------------- the client ----------------

class PayPalClient:
    def __init__(self, client_id: str, client_secret: str, *, environment: str = "sandbox", sdk=None,
                 http: httpx.Client | None = None, clock=time.monotonic):
        if environment != "sandbox":
            raise PayPalConfigError("this build only talks to the PayPal sandbox")
        if not client_id or not client_secret:
            raise PayPalConfigError("PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET are required")
        self._id, self._secret, self._clock = client_id, client_secret, clock
        self._sdk = sdk or PaypalServersdkClient(
            client_credentials_auth_credentials=ClientCredentialsAuthCredentials(o_auth_client_id=client_id, o_auth_client_secret=client_secret),
            environment=Environment.SANDBOX, timeout=20, max_retries=0)
        self._http = http or httpx.Client(base_url=SANDBOX_API, timeout=20)
        self._token: tuple[str, float] | None = None

    def __repr__(self) -> str:  # never include the credentials
        return "PayPalClient(sandbox)"

    # ----- plumbing -----
    def _bearer(self) -> str:
        """OAuth token for the httpx calls (the SDK manages its own). Cached until 60 s before expiry."""
        if self._token and self._clock() < self._token[1]:
            return self._token[0]
        r = self._http.post("/v1/oauth2/token", data={"grant_type": "client_credentials"}, auth=(self._id, self._secret))
        if r.status_code != 200:
            raise PayPalWriteError(f"PayPal rejected the credentials ({r.status_code})", transient=r.status_code >= 500)
        data = r.json()
        self._token = (data["access_token"], self._clock() + max(30, int(data.get("expires_in", 300)) - 60))
        return self._token[0]

    def _http_json(self, method: str, path: str, *, json_body: dict | None = None, headers: dict | None = None) -> dict:
        h = {"Authorization": f"Bearer {self._bearer()}", "Content-Type": "application/json", **(headers or {})}
        r = self._http.request(method, path, json=json_body, headers=h)
        if r.status_code >= 400:
            try:
                data = r.json()
            except ValueError:
                data = {}
            msg = data.get("message") or data.get("name") or r.reason_phrase
            raise PayPalWriteError(f"PayPal {r.status_code}: {msg}", transient=_is_transient(r.status_code), debug_id=data.get("debug_id"))
        return r.json() if r.content else {}

    # ================= reader (Guardian) =================
    def _read(self, call, options) -> object | None:
        try:
            return call(options).body
        except ApiException as e:
            if e.response_code == 404:
                return None
            raise PayPalUnavailable(f"PayPal {e.response_code} on a lookup") from e
        except CONNECTION_ERRORS as e:
            raise PayPalUnavailable(f"could not reach PayPal: {type(e).__name__}") from e

    def get_authorization(self, authorization_id: str) -> PayPalObject | None:
        a = self._read(self._sdk.payments.get_authorized_payment, {"authorization_id": authorization_id})
        return None if a is None else PayPalObject(_status(a), value_to_cents(a.amount.value), a.amount.currency_code)

    def get_capture(self, capture_id: str) -> PayPalObject | None:
        c = self._read(self._sdk.payments.get_captured_payment, {"capture_id": capture_id})
        return None if c is None else PayPalObject(_status(c), value_to_cents(c.amount.value), c.amount.currency_code)

    def platform_balance_cents(self) -> int | None:
        """USD balance of the platform account (G-08). None if Transaction Search is not enabled for the app."""
        try:
            body = self._sdk.transaction_search.search_balances({"currency_code": "USD"}).body
        except ApiException as e:
            if e.response_code in (400, 401, 403, 404):
                return None  # not enabled / not permitted: the rule reports SKIPPED rather than failing
            raise PayPalUnavailable(f"PayPal {e.response_code} on a balance lookup") from e
        except CONNECTION_ERRORS as e:
            raise PayPalUnavailable(f"could not reach PayPal: {type(e).__name__}") from e
        balances = [b for b in (_opt(body, "balances") or []) if _opt(b, "currency") == "USD" and _opt(b, "total_balance") is not None]
        if not balances:
            return None
        chosen = next((b for b in balances if _opt(b, "primary")), balances[0])
        return value_to_cents(chosen.total_balance.value)

    # ================= writer (money_executor only) =================
    def _write(self, call, options):
        try:
            return call(options)
        except (ApiException, *CONNECTION_ERRORS) as e:
            raise _write_error(e) from e

    def capture_authorization(self, authorization_id: str, amount_cents: int, currency: str, final_capture: bool, request_id: str) -> dict:
        r = self._write(self._sdk.payments.capture_authorized_payment, {
            "authorization_id": authorization_id, "paypal_request_id": request_id, "prefer": "return=representation",
            "body": CaptureRequest(amount=_money(amount_cents, currency), final_capture=final_capture)})
        return {"id": r.body.id, "status": _status(r.body), "amount_cents": amount_cents}

    def void_authorization(self, authorization_id: str, request_id: str) -> dict:
        self._write(self._sdk.payments.void_payment, {"authorization_id": authorization_id, "paypal_request_id": request_id})
        return {"id": authorization_id, "status": "VOIDED"}  # PayPal answers 204 with no body

    def refund_capture(self, capture_id: str, amount_cents: int, currency: str, request_id: str) -> dict:
        r = self._write(self._sdk.payments.refund_captured_payment, {
            "capture_id": capture_id, "paypal_request_id": request_id, "prefer": "return=representation",
            "body": RefundRequest(amount=_money(amount_cents, currency))})
        return {"id": r.body.id, "status": _status(r.body), "amount_cents": amount_cents}

    def create_payout_batch(self, sender_batch_id: str, items: list[dict], currency: str, email_subject: str, request_id: str) -> dict:
        """Payouts v1 (not in the SDK). One item per recipient; `sender_item_id` makes retries safe."""
        if currency != "USD":
            raise PayPalWriteError(f"only USD is supported in this build, not {currency}", transient=False)
        body = {"sender_batch_header": {"sender_batch_id": sender_batch_id, "email_subject": email_subject[:120],
                                        "email_message": "Work verified and approved. This is your payout."},
                "items": [{"recipient_type": "EMAIL", "receiver": i["receiver"],
                           "amount": {"value": cents_to_value(i["amount_cents"]), "currency": currency},
                           "note": i.get("note", "BriefPay payout")[:200], "sender_item_id": i["sender_item_id"]} for i in items]}
        try:
            data = self._http_json("POST", "/v1/payments/payouts", json_body=body, headers={"PayPal-Request-Id": request_id})
        except CONNECTION_ERRORS as e:
            raise _write_error(e) from e
        head = data.get("batch_header", {})
        return {"id": head.get("payout_batch_id"), "status": head.get("batch_status", "PENDING")}

    # ================= payout polling and webhook verification (httpx) =================
    def get_payout_batch(self, payout_batch_id: str) -> dict:
        """Batch webhooks carry no item details, so statuses are fetched here (SPEC 9.4)."""
        try:
            data = self._http_json("GET", f"/v1/payments/payouts/{payout_batch_id}")
        except PayPalWriteError as e:
            raise PayPalUnavailable(str(e)) from e
        except CONNECTION_ERRORS as e:
            raise PayPalUnavailable(f"could not reach PayPal: {type(e).__name__}") from e
        items = [{"payout_item_id": i.get("payout_item_id"), "transaction_status": i.get("transaction_status"),
                  "sender_item_id": i.get("payout_item", {}).get("sender_item_id"), "receiver": i.get("payout_item", {}).get("receiver"),
                  "amount_cents": value_to_cents(i.get("payout_item", {}).get("amount", {}).get("value", "0"))}
                 for i in data.get("items", [])]
        return {"batch_status": data.get("batch_header", {}).get("batch_status"), "items": items}

    def verify_webhook_signature(self, headers: dict[str, str], raw_body: str, webhook_id: str) -> bool:
        """True only if PayPal itself says SUCCESS. An unreachable PayPal raises PayPalUnavailable (reply 5xx; PayPal retries)."""
        h = {k.lower(): v for k, v in headers.items()}
        try:
            event = json.loads(raw_body)
        except ValueError:
            return False
        need = ("paypal-transmission-id", "paypal-transmission-time", "paypal-cert-url", "paypal-auth-algo", "paypal-transmission-sig")
        if any(k not in h for k in need) or not webhook_id:
            return False
        try:
            data = self._http_json("POST", "/v1/notifications/verify-webhook-signature", json_body={
                "transmission_id": h[need[0]], "transmission_time": h[need[1]], "cert_url": h[need[2]], "auth_algo": h[need[3]],
                "transmission_sig": h[need[4]], "webhook_id": webhook_id, "webhook_event": event})
        except PayPalWriteError as e:
            if e.transient:
                raise PayPalUnavailable(str(e)) from e
            return False
        except CONNECTION_ERRORS as e:
            raise PayPalUnavailable(f"could not reach PayPal: {type(e).__name__}") from e
        return data.get("verification_status") == "SUCCESS"

    # ================= buyer-side orders (Pledge Gate only) =================
    def create_authorize_order(self, amount_cents: int, currency: str, custom_id: str, description: str, request_id: str) -> dict:
        r = self._write(self._sdk.orders.create_order, {
            "paypal_request_id": request_id,
            "body": OrderRequest(intent=CheckoutPaymentIntent.AUTHORIZE, purchase_units=[PurchaseUnitRequest(
                amount=AmountWithBreakdown(currency_code=currency, value=cents_to_value(amount_cents)),
                custom_id=custom_id[:127], description=description[:127])])})
        return {"id": r.body.id, "status": _status(r.body)}

    def authorize_order(self, order_id: str, request_id: str) -> dict:
        """Authorize an APPROVED order. Returns the hold's id, status and amount plus the payer, all from PayPal's response."""
        r = self._write(self._sdk.orders.authorize_order, {"id": order_id, "paypal_request_id": request_id})
        order = r.body
        units = _opt(order, "purchase_units") or []
        auths = _opt(_opt(units[0], "payments"), "authorizations") or [] if units else []
        a = auths[0] if auths else None
        payer = _opt(order, "payer")
        return {"order_id": order.id, "status": _status(order),
                "authorization": None if a is None else {"id": a.id, "status": _status(a),
                                                         "amount_cents": value_to_cents(a.amount.value), "currency": a.amount.currency_code,
                                                         "expiration_time": _opt(a, "expiration_time")},
                "payer_email": _opt(payer, "email_address"), "payer_id": _opt(payer, "payer_id")}

    def get_order(self, order_id: str) -> dict | None:
        o = self._read(self._sdk.orders.get_order, {"id": order_id})
        return None if o is None else {"id": o.id, "status": _status(o)}


def configure_from_settings(settings) -> PayPalClient | None:
    """Called once at startup. Without credentials the placeholders in `paypal_io` stay in place (everything fails safe)."""
    from app.services import paypal_io
    if not (settings.paypal_client_id and settings.paypal_client_secret):
        return None
    client = PayPalClient(settings.paypal_client_id, settings.paypal_client_secret, environment=settings.paypal_env)
    paypal_io.configure(reader=client, writer=client, orders=client)
    return client
